"""Counting outcomes."""


def summarise(results):
    """Return counts per status and the total seconds."""
    summary = {"passed": 0, "failed": 0, "flaky": 0, "seconds": 0}
    for result in results:
        summary[result["status"]] += 1
        summary["seconds"] += result.get("seconds", 0)
    return summary

